const http=require('http'),fs=require('fs'),path=require('path');
const ROOT='/Users/markamir/Documents/GitHub/Percaal';
const PORT=Number(process.env.PORT)||8899;
const TYPES={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.woff2':'font/woff2','.ico':'image/x-icon','.json':'application/json','.mp4':'video/mp4'};
http.createServer((req,res)=>{
  let p=decodeURIComponent(req.url.split('?')[0]);
  if(p.endsWith('/')) p+='index.html';
  const file=path.join(ROOT,path.normalize(p));
  if(!file.startsWith(ROOT)){res.writeHead(403).end('Forbidden');return;}
  fs.readFile(file,(err,buf)=>{
    if(err){res.writeHead(404,{'Content-Type':'text/plain'}).end('Not found: '+p);return;}
    res.writeHead(200,{'Content-Type':TYPES[path.extname(file).toLowerCase()]||'application/octet-stream','Cache-Control':'no-store, max-age=0'});
    res.end(buf);
  });
}).listen(PORT,'127.0.0.1',()=>console.log('serving Percaal from '+ROOT+' on http://127.0.0.1:'+PORT));
